uint256 constant DONATE_AMOUNT = 2 ether;
uint256 constant DEPOSIT_AMOUNT = 1_114_100_000_000_000_000;
uint256 constant HISTORICAL_SHARE_BALANCE = 1_002_690_000_000_000_000;
